    private static let punctuation: [UInt32: UInt32] = [
        0x60: 0x27,
        0x2010: 0x2D,
        0x2011: 0x2D,
        0x2012: 0x2D,
        0x2013: 0x2D,
        0x2014: 0x2D,
        0x2018: 0x27,
        0x2019: 0x27,
        0x2212: 0x2D,
    ]
    private static let whitespace: Set<UInt32> = [0x9, 0xA, 0xB, 0xC, 0xD, 0x20, 0x85, 0xA0, 0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007, 0x2008, 0x2009, 0x200A, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000]

    private static func contains(_ point: UInt32, in ranges: [(UInt32, UInt32)]) -> Bool {
        ranges.contains { point >= $0.0 && point <= $0.1 }
    }

    static func normalize(_ value: String) -> String? {
        let points = value.unicodeScalars.map(\.value)
        guard points.allSatisfy({ contains($0, in: acceptedRanges) }) else { return nil }
        var decomposed: [UInt32] = []
        for point in points { decomposed.append(contentsOf: decomposition[point] ?? [point]) }
        var ordered: [UInt32] = []
        var segmentStart = 0
        for point in decomposed {
            let ccc = combiningClass[point] ?? 0
            ordered.append(point)
            if ccc == 0 { segmentStart = ordered.count } else {
                var index = ordered.count - 1
                while index > segmentStart && (combiningClass[ordered[index - 1]] ?? 0) > ccc {
                    ordered.swapAt(index - 1, index); index -= 1
                }
            }
        }
        var composed: [UInt32] = []
        var starterIndex: Int?
        var lastCCC: UInt8 = 0
        for point in ordered {
            let ccc = combiningClass[point] ?? 0
            if let starterIndex, lastCCC < ccc || lastCCC == 0,
               let replacement = composition[(UInt64(composed[starterIndex]) << 32) | UInt64(point)] {
                composed[starterIndex] = replacement
                continue
            }
            composed.append(point)
            if ccc == 0 { starterIndex = composed.count - 1; lastCCC = 0 } else { lastCCC = ccc }
        }
        var folded: [UInt32] = []
        for original in composed {
            let point = punctuation[original] ?? original
            folded.append(contentsOf: caseFolding[point] ?? [point])
        }
        var output: [UInt32] = []
        var pendingSpace = false
        for point in folded {
            if whitespace.contains(point) { pendingSpace = !output.isEmpty } else {
                if pendingSpace { output.append(0x20) }
                output.append(point); pendingSpace = false
            }
        }
        guard output.allSatisfy({ contains($0, in: outputRanges) }) else { return nil }
        var scalars = String.UnicodeScalarView()
        for point in output {
            guard let scalar = Unicode.Scalar(point) else { return nil }
            scalars.append(scalar)
        }
        return String(scalars)
    }

    static func normalizeLookupKey(_ value: String) -> String? {
        guard let normalized = normalize(value) else { return nil }
        let points = normalized.unicodeScalars.map(\.value)
        guard (1...100).contains(points.count) else { return nil }
        let tokens = normalized.split(separator: " ", omittingEmptySubsequences: false)
        guard (1...4).contains(tokens.count), tokens.allSatisfy({ !$0.isEmpty }) else { return nil }
        func isLetter(_ point: UInt32) -> Bool { contains(point, in: resolverLetterRanges) }
        func isDigit(_ point: UInt32) -> Bool { (0x30...0x39).contains(point) }
        func isAtomEnd(_ point: UInt32) -> Bool {
            isLetter(point) || isDigit(point) || resolverMarks.contains(point)
        }
        func isAtomStart(_ point: UInt32) -> Bool { isLetter(point) || isDigit(point) }
        var surfaceHasLetter = false
        for token in tokens {
            let tokenPoints = token.unicodeScalars.map(\.value)
            var previousWasMark = false
            for (index, point) in tokenPoints.enumerated() {
                if isLetter(point) {
                    surfaceHasLetter = true; previousWasMark = false
                } else if isDigit(point) {
                    previousWasMark = false
                } else if resolverMarks.contains(point) {
                    guard index > 0, !previousWasMark,
                          isLetter(tokenPoints[index - 1]) else { return nil }
                    previousWasMark = true
                } else if point == resolverPeriod {
                    guard index > 0, isAtomEnd(tokenPoints[index - 1]) else { return nil }
                    if index < tokenPoints.count - 1,
                       !isAtomStart(tokenPoints[index + 1]),
                       !(tokenPoints[index + 1] == resolverHyphen
                         && index + 2 < tokenPoints.count
                         && isAtomStart(tokenPoints[index + 2])) { return nil }
                    previousWasMark = false
                } else if point == resolverSlash {
                    guard index > 0, index < tokenPoints.count - 1,
                          isAtomEnd(tokenPoints[index - 1]),
                          isAtomStart(tokenPoints[index + 1]) else { return nil }
                    previousWasMark = false
                } else if point == resolverApostrophe {
                    let previous = index > 0 ? tokenPoints[index - 1] : nil
                    let following = index < tokenPoints.count - 1 ? tokenPoints[index + 1] : nil
                    let previousAtom = previous.map(isAtomEnd) ?? false
                    let followingAtom = following.map(isAtomStart) ?? false
                    guard previous != resolverApostrophe,
                          previous != resolverPeriod,
                          previous != resolverSlash,
                          following != resolverApostrophe,
                          following != resolverPeriod,
                          following != resolverSlash else { return nil }
                    if previous == resolverHyphen {
                        guard index >= 2, isAtomEnd(tokenPoints[index - 2]),
                              followingAtom else { return nil }
                    }
                    if following == resolverHyphen {
                        guard previousAtom, index + 2 < tokenPoints.count,
                              isAtomStart(tokenPoints[index + 2]) else { return nil }
                    }
                    guard previousAtom || followingAtom else { return nil }
                    previousWasMark = false
                } else if point == resolverHyphen {
                    guard index > 0, index < tokenPoints.count - 1 else { return nil }
                    let previous = tokenPoints[index - 1]
                    let following = tokenPoints[index + 1]
                    let ordinary = isAtomEnd(previous) && isAtomStart(following)
                    let afterApostrophe = previous == resolverApostrophe
                        && index >= 2
                        && isAtomEnd(tokenPoints[index - 2])
                        && isAtomStart(following)
                    let beforeApostrophe = following == resolverApostrophe
                        && index + 2 < tokenPoints.count
                        && isAtomEnd(previous)
                        && isAtomStart(tokenPoints[index + 2])
                    let afterPeriod = previous == resolverPeriod
                        && index >= 2
                        && isAtomEnd(tokenPoints[index - 2])
                        && isAtomStart(following)
                    guard ordinary || afterApostrophe || beforeApostrophe || afterPeriod else { return nil }
                    previousWasMark = false
                } else {
                    return nil
                }
            }
        }
        if !surfaceHasLetter {
            guard tokens.count == 1 else { return nil }
            let tokenPoints = tokens[0].unicodeScalars.map(\.value)
            guard tokenPoints.contains(resolverSlash),
                  tokenPoints.allSatisfy({ isDigit($0) || $0 == resolverSlash }) else {
                return nil
            }
        }
        return normalized
    }

    static func isValidResolverSurface(_ value: String) -> Bool {
        normalizeLookupKey(value) != nil
    }
}
